def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_pair(x):
        return isinstance(x, (list, tuple)) and len(x) >= 2 and isinstance(x[0], (int, float)) and isinstance(x[1], (int, float))

    def to_xy(v):
        if is_pair(v):
            return [int(v[0]), int(v[1])]
        return None

    def find_first_pos(d, keys):
        for k in keys:
            v = d.get(k)
            p = to_xy(v)
            if p is not None:
                return p
        return None

    def extract_points(v):
        pts = []
        if isinstance(v, dict):
            for vv in v.values():
                p = to_xy(vv)
                if p is not None:
                    pts.append(p)
                elif isinstance(vv, (list, tuple)):
                    for item in vv:
                        p2 = to_xy(item)
                        if p2 is not None:
                            pts.append(p2)
        elif isinstance(v, (list, tuple)):
            for item in v:
                p = to_xy(item)
                if p is not None:
                    pts.append(p)
                elif isinstance(item, dict):
                    p2 = find_first_pos(item, ("pos", "position", "loc", "location", "xy"))
                    if p2 is not None:
                        pts.append(p2)
        return pts

    obs = observation if isinstance(observation, dict) else {}

    me = find_first_pos(obs, ("self", "agent", "player", "pos", "position", "location", "loc", "xy"))
    if me is None:
        me = [0, 0]

    # Candidate targets by task type.
    resources = []
    for key in ("resources", "resource", "food", "coins", "targets", "target", "items", "pickup"):
        resources += extract_points(obs.get(key))

    enemies = []
    for key in ("enemies", "enemy", "opponents", "opponent", "hazards", "hazard", "agents"):
        enemies += extract_points(obs.get(key))

    territories = []
    for key in ("territory", "territories", "home", "bases", "base", "zones", "zone", "cells"):
        territories += extract_points(obs.get(key))

    walls = set()
    for key in ("walls", "obstacles", "blocked", "blocks"):
        for p in extract_points(obs.get(key)):
            walls.add((p[0], p[1]))

    # If a mode is hinted, bias targets accordingly.
    mode = obs.get("mode") or obs.get("task") or obs.get("scenario") or obs.get("game")
    mode = mode if isinstance(mode, str) else ""

    target = None
    if "resource" in mode or "collect" in mode:
        if resources:
            target = min(resources, key=lambda p: manhattan(me, p))
    elif "pursuit" in mode or "evade" in mode or "evasion" in mode:
        if enemies:
            target = min(enemies, key=lambda p: manhattan(me, p))
    elif "territory" in mode or "control" in mode:
        if territories:
            target = min(territories, key=lambda p: manhattan(me, p))

    # Fallback priority by presence.
    if target is None:
        if resources:
            target = min(resources, key=lambda p: manhattan(me, p))
        elif enemies:
            # In pursuit/evasion, if we are stronger/advantaged, approach; otherwise keep distance.
            threat = obs.get("threat", obs.get("danger", 0))
            if isinstance(threat, (int, float)) and threat > 0:
                # Move away from nearest enemy.
                nearest = min(enemies, key=lambda p: manhattan(me, p))
                target = [me[0] + (me[0] - nearest[0]), me[1] + (me[1] - nearest[1])]
            else:
                target = min(enemies, key=lambda p: manhattan(me, p))
        elif territories:
            target = min(territories, key=lambda p: manhattan(me, p))

    dx = 0
    dy = 0
    if target is not None:
        dx = clamp_step(target[0] - me[0])
        dy = clamp_step(target[1] - me[1])

    # Prefer axis with larger gap if both possible.
    if dx != 0 and dy != 0:
        if abs(target[0] - me[0]) > abs(target[1] - me[1]):
            dy = 0
        else:
            dx = 0

    # Simple obstacle avoidance: try alternatives if blocked.
    def blocked(stepx, stepy):
        nx, ny = me[0] + stepx, me[1] + stepy
        return (nx, ny) in walls

    if blocked(dx, dy):
        candidates = [
            (dx, 0),
            (0, dy),
            (dx, -dy if dy != 0 else 0),
            (-dx if dx != 0 else 0, dy),
            (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)
        ]
        best = (0, 0)
        best_score = None
        for sx, sy in candidates:
            if abs(sx) > 1 or abs(sy) > 1:
                continue
            if blocked(sx, sy):
                continue
            score = 0
            if target is not None:
                score = manhattan([me[0] + sx, me[1] + sy], target)
            if best_score is None or score < best_score:
                best_score = score
                best = (sx, sy)
        dx, dy = best

    if dx not in (-1, 0, 1):
        dx = clamp_step(dx)
    if dy not in (-1, 0, 1):
        dy = clamp_step(dy)

    return [dx, dy]

